    State snapshot(){return new State(this);}
    void restore(State value){if(value==null||host.runner()!=value.runner||value.runner==null||value.runner.generation()!=value.generation)return;sync=true;try{session.restore(value.comparisonHistory);search.setText(value.query);follow.setChecked(value.follow);selected=value.selected;offset=value.offset;evaluationDraft=value.evaluationDraft;watches.restore(value.watches);}finally{sync=false;}refresh();if(value.watchOpen)showWatches();else if(value.evaluation!=null)showEvaluation(value.evaluation);else if(value.valueDetailName!=null&&inspection!=null){FlowVariableInspection.Row selected=inspection.find(value.valueDetailName);if(selected!=null)showValue(selected);}}
    void refresh(){
        if(closed)return;FlowEngine.Runner r=host.runner();boolean changed=r!=observed||r!=null&&generation!=r.generation();
        if(changed){closeChildren(true);selected=0;follow.setChecked(true);offset=0;notice=null;lastSend=-1000;waitingKey=null;session.clear();}observed=r;generation=r==null?-1:r.generation();
        FlowVariableInspection before=inspection;inspection=session.read(r,follow.isChecked()?0:selected,!host.running());
        if(inspection!=null&&inspection.fallback){selected=0;follow.setChecked(true);offset=0;notice="La chiamata è terminata. Seguo quella attiva.";inspection=session.read(r,0,!host.running());}
        if(before!=inspection){frames.setLabel(inspection==null||inspection.frame==null?"Nessuna chiamata":inspection.frame.functionName+" · "+inspection.frames.size()+" chiamate");renderRows();}
        evaluateExpression.setEnabled(inspection!=null&&inspection.frame!=null);frames.setEnabled(inspection!=null&&!inspection.frames.isEmpty());follow.setEnabled(inspection!=null);save.setEnabled(inspection!=null&&!inspection.rows.isEmpty());
        boolean waiting=r!=null&&r.state==FlowEngine.State.WAITING,fileWait=r!=null&&r.state==FlowEngine.State.WAITING_FILE,done=r!=null&&(r.state==FlowEngine.State.COMPLETED||r.state==FlowEngine.State.ERROR);
        String key=waiting?r.generation()+":"+r.currentFrameId()+":"+r.currentVisit()+":"+r.inputVariable:null;boolean newQuestion=changed||!Objects.equals(waitingKey,key);waitingKey=key;
        inputArea.setVisibility(waiting?View.VISIBLE:View.GONE);question.setVisibility(waiting?View.VISIBLE:View.GONE);controls.setVisibility(waiting||fileWait?View.GONE:View.VISIBLE);file.setVisibility(fileWait?View.VISIBLE:View.GONE);
        if(waiting){question.setText(r.inputPrompt);input.setHint(r.inputVariable);input.setContentDescription("Valore per "+r.inputVariable);String pending=host.pending()==null?"":host.pending();if(newQuestion||!input.getText().toString().equals(pending)){sync=true;try{input.setText(pending);if(newQuestion)input.setError(null);}finally{sync=false;}}}
        send.setEnabled(waiting);play.setLabel(host.running()?"Pausa":done?"Riprova":r!=null&&r.steps>0?"Riprendi":"Esegui");play.setEnabled(r!=null&&!waiting&&!fileWait);step.setEnabled(r!=null&&!host.running()&&!waiting&&!fileWait&&!done);
        String state=r==null?"Avvia una prova per vedere i valori.":r.state==FlowEngine.State.ERROR?"Interrotto: "+r.errorMessage:r.state==FlowEngine.State.COMPLETED?"Completato":waiting?"In attesa di "+r.inputVariable:fileWait?"Scegli il file per continuare":host.running()?"In esecuzione":"In pausa";
        status.setText((notice==null?state:notice)+(r==null?"":" · passo "+r.steps));
        watchExpressions.setLabel("Espressioni osservate"+(watches.expressions().isEmpty()?"":" · "+watches.expressions().size()));refreshWatches();
    }
    private void showWatches(){host.pause();refresh();if(watchPanel!=null){watchPanel.sheet.dialog.show();return;}Ui.Sheet child=child("Espressioni osservate",null);FlowWatchPanel panel=new FlowWatchPanel(owner,child,host,watches,value->clipboardWrite.accept(value));watchPanel=panel;child.dialog.setOnDismissListener(d->{panel.close();children.remove(child);if(watchPanel==panel)watchPanel=null;refresh();});refreshWatches();child.show();}
