        host.pause();refresh();if(inspection==null||inspection.frame==null)return;FlowEngine.Runner runner=host.runner();FlowInspectExpression.Context context=restored==null?new FlowInspectExpression.Context(inspection.frame,inspection.steps,runner==null?null:runner.files::eof):restored.context;
