    private void systemClipboard(String text){((android.content.ClipboardManager)owner.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Variabile Frociart",text));}
    private boolean canSend(){FlowEngine.Runner r=host.runner();return !closed&&r!=null&&r==observed&&generation==r.generation()&&r.state==FlowEngine.State.WAITING;}
    private void submit(){if(!canSend()||SystemClock.uptimeMillis()-lastSend<250)return;FlowEngine.Runner r=observed;long revision=r.consoleLog.revision();host.submit(input.getText().toString());boolean accepted=r.consoleLog.revision()!=revision;if(accepted){lastSend=SystemClock.uptimeMillis();notice=null;if(r.state!=FlowEngine.State.WAITING)Ui.dismissKeyboard(input);}else{input.setError(r.errorMessage==null?r.lastMessage:r.errorMessage);input.requestFocus();}refresh();}
